const open=()=>new Promise((ok,no)=>{const r=indexedDB.open(DB,4);r.onupgradeneeded=e=>{const d=r.result;if(e.oldVersion<1){d.createObjectStore('profile',{keyPath:'k'});ST1.forEach(s=>d.createObjectStore(s,{keyPath:'id',autoIncrement:true}))}if(e.oldVersion<2)d.createObjectStore('days',{keyPath:'date'});if(e.oldVersion<3)d.createObjectStore('photos',{keyPath:'id',autoIncrement:true});if(e.oldVersion<4)d.createObjectStore('exercises',{keyPath:'id',autoIncrement:true});};r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});
async function load0(){for(const s of ST)D[s]=await all(s);D.me=await req(tx('profile').get('me'))||{k:'me',name:'',water:2000,kcal:0,protein:0};D.n=await req(tx('profile').get('notif'))||ASTRA.defaults();D.photos=await all('photos')}
