const ring=(v,m,l,s)=>{const r=44,c=2*Math.PI*r,p=Math.min(1,m?v/m:0);return `<svg class="ring" viewBox="0 0 100 100"><circle cx="50" cy="50" r="${r}" class="rt"/><circle cx="50" cy="50" r="${r}" class="rp" stroke-dasharray="${c*p} ${c}" transform="rotate(-90 50 50)"/><text x="50" y="52" text-anchor="middle" class="rl">${l}</text><text x="50" y="66" text-anchor="middle" class="rs">${s}</text></svg>`};
const spark=v=>{if(v.length<2)return '<span class="muted">1 point</span>';const mn=Math.min(...v),mx=Math.max(...v),g=mx-mn||1;return `<svg class="sp" viewBox="0 0 100 30" preserveAspectRatio="none"><polyline points="${v.map((y,i)=>`${i/(v.length-1)*100},${28-(y-mn)/g*24}`).join(' ')}"/></svg>`};
