async function imp(f){try{const j=JSON.parse(await f.text());if(j.app!=='orrery'||!ST.every(s=>!ST1.includes(s)||Array.isArray(j[s])))throw 0;if(!confirm('Restoring replaces everything currently in the app. Export a backup first if unsure. Continue?'))return;await wipe(false);for(const s of ST)for(const r of (j[s]||[]))await put(s,r);if(j.me?.k)await put('profile',j.me);if(j.n?.k)await put('profile',j.n);await put('profile',{k:'libseed',v:1});await load();render();toast('Backup restored')}catch{toast('That file is not a valid ASTRA backup')}}
