addset:b=>{const s=draft.ex[I(b)].sets;s.push({...(s.at(-1)||{w:'',r:''}),wu:false})},rmset:b=>draft.ex[I(b)].sets.splice(+b.dataset.j,1),dup:b=>draft.ex.splice(I(b)+1,0,structuredClone(draft.ex[I(b)])),
