preset:b=>{clearInterval(T.id);T.id=null;T.left=T.set=+b.dataset.s},treset:()=>{clearInterval(T.id);T.id=null;T.left=T.set},tgo:()=>{if(T.id){clearInterval(T.id);T.id=null}else if(T.left>0)T.id=setInterval(tick,1e3)},
addw:b=>addH(+b.dataset.ml),cw:async()=>{const v=+N('#cml');if(v>0&&v<=5000){await addH(v,N('#bev'));toast('Added')}else toast('Enter an amount from 1 to 5000 ml')},delh:async b=>{await rm('hydration',ID(b));await load()},
