const waterExtra=()=>{const t=today(),ds=range(addDays(t,-29),t),vs=ds.map(wat),lg=vs.filter(v=>v>0),tg=D.me.water||2000;return `<section class="card"><h2>Target and history</h2><label><small>Daily water target in ml. This is your own choice.</small><input type="number" data-p="water" min="200" max="8000" value="${tg}"></label><p class="muted">${lg.length?`Last 30 days: average ${Math.round(lg.reduce((a,b)=>a+b)/lg.length)} ml on ${lg.length} logged days. Target reached on ${vs.filter(v=>v>=tg).length}.`:'Nothing logged in the last 30 days.'}</p>${bars(ds.map((d,i)=>({l:d.slice(5),v:vs[i]})),'ml')}</section>`};
let fed=null;const fm=k=>{const m=fed&&D.nutrition.find(x=>x.id===fed);return m?esc(m[k]||''):''};
function recentMeals(){const seen=new Set(),r=[...D.nutrition].sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id).filter(m=>{const k=(m.label||'').toLowerCase()+m.kcal;if(seen.has(k)||m.date===fday)return false;seen.add(k);return true}).slice(0,5),t=today();return `${r.length?'<p class="eyebrow">Recent meals, one tap to add</p>'+r.map(m=>`<div class="li"><div><b>${esc(m.label)}</b><small>${m.kcal} kcal, P ${m.p}, C ${m.c}, F ${m.f}</small></div><button class="btn sm" data-act="radd" data-id="${m.id}">Add</button></div>`).join(''):''}<p class="eyebrow">Calories, last 7 days</p>${bars(range(addDays(t,-6),t).map(d=>({l:d.slice(5),v:sum(day('nutrition',d),'kcal')})),'kcal')}`}
const lastChk=()=>{const d=mdates();return d.length?`<p class="eyebrow">Last check-in ${gap(today(),d.at(-1))} days ago.</p>`:''};
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.rk){await setDay(rcd,t.dataset.rk,t.type==='number'&&t.value!==''?+t.value:t.value);const p=$('#pat');if(p)p.innerHTML=patterns()}else if(t.id==='rcd'){rcd=t.value||today();render()}else if(t.id==='sxs'){sx=t.value;render()}else if(t.id==='mxs'){mx2=t.value;render()}});
Object.assign(A,{rset:b=>setDay(rcd,b.dataset.k,dayRec(rcd)[b.dataset.k]===+b.dataset.v?'':+b.dataset.v),rrest:()=>setDay(rcd,'rest',!dayRec(rcd).rest),ract:b=>{const a=dayRec(rcd).act||[],x=b.dataset.a;return setDay(rcd,'act',a.includes(x)?a.filter(y=>y!==x):[...a,x])},rnav:b=>{rcd=addDays(rcd,+b.dataset.d)},dnav:b=>{rday=+b.dataset.d?addDays(rday,+b.dataset.d):today()},rg:b=>{rg=b.dataset.k},
addmeal:async()=>{const g=k=>+N('#m'+k)||0;if(!g('k')&&!g('p')&&!g('c')&&!g('f'))return toast('Enter at least one value');const o={date:fday,label:N('#ml').trim()||'Meal',kcal:g('k'),p:g('p'),c:g('c'),f:g('f')};if(fed){await put('nutrition',{...D.nutrition.find(x=>x.id===fed),...o});fed=null;toast('Meal updated')}else await put('nutrition',o);await load()},
fedit:b=>{fed=ID(b)},fcancel:()=>{fed=null},radd:async b=>{const{id,...r}=D.nutrition.find(x=>x.id===ID(b));await put('nutrition',{...r,date:fday});await load()},
exp:async()=>{D.me.lastBackup=today();dl(`orrery-backup-${today()}.json`,JSON.stringify({app:'orrery',v:1,me:D.me,n:D.n,...Object.fromEntries(ST.map(s=>[s,D[s]]))}),'application/json');await put('profile',D.me);toast('Backup downloaded')},
expm:()=>{const r=[['date','measurement','value','unit']];[...D.measurements].sort((a,b)=>a.date.localeCompare(b.date)).forEach(m=>r.push([m.date,m.m,m.v,mu(m.m)]));dl('measurements.csv',r.map(x=>x.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(',')).join('\n'),'text/csv')}});

